<?php require_once 'config.php'; if(current_user()) redirect('account.php'); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'&&verify_csrf($_POST['csrf']??null)){ $name=trim($_POST['full_name']);$username=trim($_POST['username']);$email=trim($_POST['email']);$phone=trim($_POST['phone']); if(!rate_limit('register',5,900))$error='Too many signup attempts. Please wait and try again.'; elseif(!filter_var($email,FILTER_VALIDATE_EMAIL))$error='Enter a valid email address.'; elseif($_POST['password']!==$_POST['confirm_password'])$error='Passwords do not match.'; elseif(strlen($_POST['password'])<8)$error='Use at least 8 characters for your password.'; else {try{$token=bin2hex(random_bytes(32));$stmt=db()->prepare('INSERT INTO users(full_name,username,email,phone,password_hash,verification_token) VALUES (?,?,?,?,?,?)');$stmt->execute([$name,$username,$email,$phone,password_hash($_POST['password'],PASSWORD_DEFAULT),$token]);$_SESSION['verification_link']=BASE_URL.'verify.php?token='.$token;flash('success','Account created. Verify your email before signing in.');redirect('login.php');}catch(PDOException $e){$error=$e->getCode()==='23000'?'That email or username is already registered.':'We could not create your account.';}}} $pageTitle='Create account';include 'includes/header.php'; ?>
<section class="section"><div class="container" style="max-width:650px"><div class="form-card"><div class="eyebrow">Join the flock</div><h1>Create an account.</h1><p>Save your details, track orders and get farm updates.</p><?php if($error): ?><div class="toast-error notice"><?= e($error) ?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><div class="form-row"><div class="form-group"><label>Full name</label><input class="form-control" name="full_name" required></div><div class="form-group"><label>Username</label><input class="form-control" name="username" required></div></div><div class="form-row"><div class="form-group"><label>Email</label><input class="form-control" type="email" name="email" required></div><div class="form-group"><label>Phone number</label><input class="form-control" name="phone" required></div></div><div class="form-row"><div class="form-group"><label>Password</label><input class="form-control" type="password" name="password" minlength="8" required></div><div class="form-group"><label>Confirm password</label><input class="form-control" type="password" name="confirm_password" required></div></div><button class="btn btn-primary">Create account →</button></form></div></div></section><?php include 'includes/footer.php'; ?>
